<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">ADMINISTRATION ACCOUNTS</span><h2>حسابات الإدارة</h2><p>هذه الصفحة تفصل المديرين عن الكتّاب. لا يمكن تعطيل حسابك أو آخر مدير نشط، وتغيير الأدوار غير متاح دون طبقة Super Administrator مستقلة.</p></div></section>
<section class="admin-v2-table-panel"><div class="admin-v2-table-wrap"><table class="admin-v2-table"><thead><tr><th>المدير</th><th>الحالة</th><th>الحماية</th><th>الإنشاء</th><th>آخر دخول</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e((string)$row['name'])?></strong><small>@<?=e((string)$row['username'])?> · <?=e((string)$row['email'])?></small></td><td><span class="admin-v2-badge <?=e((string)$row['status'])?>"><?=e((string)$row['status'])?></span></td><td><?=!empty($row['two_factor_enabled'])?'<span class="admin-v2-badge good">2FA مفعّل</span>':'<span class="admin-v2-badge warning">2FA غير مفعّل</span>'?></td><td><?=e((string)$row['created_at'])?></td><td><?=e((string)($row['last_login_at']??'—'))?></td><td><?php if((int)$row['id']!==(int)$u['id']):?><form method="post" action="/admin-v2/administrators/action"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><button class="admin-v2-small-button <?=($row['status']==='active'?'danger':'good')?>" name="action" value="<?=($row['status']==='active'?'disable':'enable')?>" type="submit"><?=($row['status']==='active'?'تعطيل الوصول':'تفعيل الوصول')?></button></form><?php else:?><span class="admin-v2-muted">حسابك الحالي</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
